class Solution {
    public String shortestPalindrome(String s) {
        String rev = new StringBuilder(s).reverse().toString();
        String combined = s + "#" + rev;
        int[] fail = new int[combined.length()];
        for (int i = 1; i < combined.length(); i++) {
            int j = fail[i - 1];
            while (j > 0 && combined.charAt(i) != combined.charAt(j)) j = fail[j - 1];
            if (combined.charAt(i) == combined.charAt(j)) j++;
            fail[i] = j;
        }
        int palLen = fail[combined.length() - 1];
        return rev.substring(0, s.length() - palLen) + s;
    }
}

class Solution {
    public String shortestPalindrome(String s) {
        if (s.length() <= 1) return s;
        long MOD = 1000000007L;
        long BASE = 31L;
        long forwardHash = 0, backwardHash = 0;
        long power = 1;
        int bestLen = 0;
        for (int i = 0; i < s.length(); i++) {
            int c = s.charAt(i) - 'a' + 1;
            forwardHash = (forwardHash * BASE + c) % MOD;
            backwardHash = (backwardHash + c * power) % MOD;
            power = (power * BASE) % MOD;
            if (forwardHash == backwardHash) {
                bestLen = i + 1;
            }
        }
        String suffix = s.substring(bestLen);
        String reversed = new StringBuilder(suffix).reverse().toString();
        return reversed + s;
    }
}
